    sd = SwerveDrive()
    ctx = AutoContext(sd, Intake(), Controller(), Odometry(sd))
    r = AutoRunner("temp.traj")
    assert r.first_iteration == True
    r.execute(ctx)
    assert r.first_iteration == False

    # runs once AND Try branch
    r.contents = json.loads("""
            {
                "trajectory": {
                    "samples": {}
                },
                "events": {}
            }
        """)
    r.execute(ctx)

    # runs zero times AND Except branch
    r.contents = json.loads("{}")
    r.execute(ctx)
    assert "Malformed Trajectory file, auto stopping" in AlertManager.get_strings(
        AlertType.WARNING
    )
    r.contents = {"trajectory": {"samples": []}, "events": []}
    ctx.it.set_voltage(units.volts(0))
    r.execute(ctx)
    assert ctx.it.spin_voltage == units.volts(0)
    r.contents = {
        "trajectory": {"samples": []},
        "events": [{"name": "IntakeOn", "from": {"targetTimestamp": 0.0}}],
    }
    ctx.it.set_voltage(units.volts(0))
    r.execute(ctx)
    assert ctx.it.spin_voltage == units.volts(12)
    r.contents = {
        "trajectory": {"samples": []},
        "events": [
            {"name": "IntakeOn", "from": {"targetTimestamp": 5.0}},
            {"name": "IntakeOff", "from": {"targetTimestamp": 5.0}},
            {"name": "IntakeOn", "from": {"targetTimestamp": 0.0}},
        ],
    }
    ctx.it.set_voltage(units.volts(0))
    r.execute(ctx)
    assert ctx.it.spin_voltage == units.volts(12)
    os.remove("temp.traj")
